using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpRestServer;

/// <summary>
/// MCP tools that wrap the Open-Meteo weather REST API.
/// Each [McpServerTool] method becomes a callable tool for LLMs.
/// Constructor-injected HttpClient is provided via DI (see Program.cs).
/// </summary>
[McpServerToolType]
public class WeatherTools(HttpClient httpClient)
{
    private static readonly JsonSerializerOptions JsonOptions = new() { PropertyNameCaseInsensitive = true };

    [McpServerTool, Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken = default)
    {
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m,relative_humidity_2m";

        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        var forecast = JsonSerializer.Deserialize<JsonElement>(json, JsonOptions);
        var current = forecast.GetProperty("current");

        return $"Temperature: {current.GetProperty("temperature_2m")}°C, "
             + $"Wind: {current.GetProperty("wind_speed_10m")} km/h, "
             + $"Humidity: {current.GetProperty("relative_humidity_2m")}%";
    }

    [McpServerTool, Description("Get a daily weather forecast for the next N days (max 16).")]
    public async Task<string> GetForecast(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        [Description("Number of forecast days (1-16)")] int days = 7,
        CancellationToken cancellationToken = default)
    {
        days = Math.Clamp(days, 1, 16);
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={latitude}&longitude={longitude}"
                + $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}";

        var response = await httpClient.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        var forecast = JsonSerializer.Deserialize<JsonElement>(json, JsonOptions);
        var daily = forecast.GetProperty("daily");
        var dates = daily.GetProperty("time").EnumerateArray().ToArray();
        var highs = daily.GetProperty("temperature_2m_max").EnumerateArray().ToArray();
        var lows = daily.GetProperty("temperature_2m_min").EnumerateArray().ToArray();

        var lines = dates.Select((d, i) =>
            $"{d.GetString()}: High {highs[i]}°C, Low {lows[i]}°C");

        return string.Join("\n", lines);
    }
}

